    required this.ownerUserId,
    required this.updatedAt,
    required this.updatedByDevice,
    required this.hlc,
    this.deletedAt,
    required this.id,
    required this.strategy,
    required this.symbol,
    required this.optionSymbol,
    required this.openedAt,
    this.closedAt,
    required this.entryCredit,
